begin;
create extension if not exists pgtap with schema extensions;
select plan(12);
insert into public.work_cards(company_id,status,title) values ('10000000-0000-0000-0000-000000000002','ideas','Company B private card');
select set_config('test.company_b_card',(select id::text from public.work_cards where company_id='10000000-0000-0000-0000-000000000002' and title='Company B private card'),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select is((select count(*)::int from public.work_cards where company_id='10000000-0000-0000-0000-000000000002'),0,'company B cards are hidden');
select is((select count(*)::int from public.work_projects where company_id='10000000-0000-0000-0000-000000000002'),0,'company B projects are hidden');
select is((select count(*)::int from public.work_activity where company_id='10000000-0000-0000-0000-000000000002'),0,'company B activity is hidden');
-- An Agent writes the board as a Contributor, with the functions a Member uses (#684: its own board write is gone).
select throws_ok($$select public.new_card('10000000-0000-0000-0000-000000000002','Denied','ideas')$$,'42501',null,'agent cannot create for another company');
select throws_ok($$select public.save_card('10000000-0000-0000-0000-000000000002',current_setting('test.company_b_card')::bigint,'title','Changed',null)$$,null,null,'agent cannot edit another company');
select throws_ok($$select public.move_card('10000000-0000-0000-0000-000000000001',1,'waiting',null,null)$$,'42501','waiting is not placed by hand','agent cannot put a Card in Waiting on you');
select throws_ok($$select public.decide_review('10000000-0000-0000-0000-000000000001',5,null,'approve',null)$$,null,null,'contributor cannot approve');
select lives_ok($$select public.new_card('10000000-0000-0000-0000-000000000001','Idempotent','planned',request_key=>'a6840000-0000-0000-0000-00000000000a')$$,'an agent makes a Card');
select is(public.new_card('10000000-0000-0000-0000-000000000001','Idempotent','planned',request_key=>'a6840000-0000-0000-0000-00000000000a'),(select id from public.work_cards where title='Idempotent'),'a retry with the same key returns the same Card');
select is((select count(*)::int from public.work_cards where company_id='10000000-0000-0000-0000-000000000001' and title='Idempotent'),1,'retry creates one card');
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'comment','{"body":"agent comment"}')$$,'agent comments');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.change_work_card('10000000-0000-0000-0000-000000000001',1,'comment','{"body":"human comment"}')$$,'person comments');
reset role;
select * from finish();
rollback;
